"""Build one portable, source-attributed Chinese brand narrative HTML."""
import base64
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[4]
OUT = ROOT / 'output/wqt-brand-story'
ASSETS = OUT / 'assets'


def img(name, alt, cls='', eager=False):
    data = base64.b64encode((ASSETS / name).read_bytes()).decode('ascii')
    return f'<img class="{cls}" src="data:image/png;base64,{data}" alt="{alt}" loading="{"eager" if eager else "lazy"}" decoding="async">'


def ref(*ids):
    return '<span class="refs">' + ''.join(f'<a href="#source-{i}" aria-label="查看来源{i}">[{i}]</a>' for i in ids) + '</span>'


def heading(n, label, title, lead):
    return f'<header class="section-head"><span class="section-index">{n}</span><div><p class="eyebrow">{label}</p><h2>{title}</h2><p class="section-lead">{lead}</p></div></header>'


navs = [('identity','品牌身份'),('context','时代命题'),('method','成长方法'),('journey','品牌历程'),('products','产品体系'),('actions','六类行动'),('ecosystem','共建生态'),('narrative','完整叙事'),('sources','资料依据')]
nav = ''.join(f'<a href="#{id_}"><span>{i:02}</span>{title}</a>' for i,(id_,title) in enumerate(navs,1))

