js = r'''
const mode=document.querySelector('#mode');
const status=document.querySelector('#reading-state');
mode.addEventListener('click',()=>{const on=document.body.classList.toggle('compact');mode.setAttribute('aria-pressed',String(on));mode.textContent=on?'完整阅读':'结构速览';status.textContent=on?'当前为结构速览。切换“完整阅读”可查看全部正文与插画。':'当前为完整阅读。可切换“结构速览”，快速查看叙事框架。';});
document.querySelector('#print').addEventListener('click',()=>window.print());
const links=[...document.querySelectorAll('.nav a')];
const targets=links.map(a=>document.querySelector(a.getAttribute('href')));
function markSection(){let selected=targets[0];for(const section of targets){if(section.getBoundingClientRect().top<=140)selected=section;}for(const a of links){const active=a.getAttribute('href')==='#'+selected.id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');}}
let scheduled=false;window.addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(()=>{markSection();scheduled=false;});}},{passive:true});
window.addEventListener('resize',markSection);markSection();
let expandedForPrint=[];window.addEventListener('beforeprint',()=>{expandedForPrint=[...document.querySelectorAll('details:not([open])')];expandedForPrint.forEach(e=>e.open=true);});window.addEventListener('afterprint',()=>expandedForPrint.forEach(e=>e.open=false));
'''

